# Compare style sigs for ALL non-empty cells in golden vs filled across full sheet including row1 and C
import openpyxl, datetime
from openpyxl import load_workbook
filled = load_workbook('3_32023_answer_template_1265_input_filled.xlsx')
golden = load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_32023_answer_template_1265_golden.xlsx')
fw=filled['Sheet1']; gw=golden['Sheet1']
def sig(c):
    return (c.style_id, c.number_format, c.fill.fill_type, getattr(c.fill.fgColor,'rgb',None), getattr(c.fill.bgColor,'rgb',None),
            c.border.left.style, c.border.right.style, c.border.top.style, c.border.bottom.style,
            c.font.bold, c.font.name, c.font.sz, c.alignment.horizontal, c.alignment.wrap_text)
diffs=[]
for row in range(1,20):
    for col in 'ABCDEFGHIJKLMNOPQRSTUVW':
        coord=f'{col}{row}'
        f=fw[coord]; g=gw[coord]
        if f.value is not None or g.value is not None:
            if sig(f)!=sig(g):
                diffs.append((coord, sig(f), sig(g), repr(f.value), repr(g.value)))
print('style diffs among non-empty:', len(diffs))
for d in diffs[:20]:
    print(d)
